1	// Acceptance test for the change request:
2	//   "Let me mark an invoice as paid. Keep a record every time I do so I can check back later."
3	//
4	// Invoices move through stages (draft → sent → paid), and payment is only offered once an invoice has
5	// been SENT — so the invoices here are seeded in the SENT stage, which is where the pay control
6	// (invoice-pay-<id>) is available. On a project's detail page each invoice shows its status
7	// (invoice-status). Marking a sent invoice paid flips its status to paid, survives a fresh load from
8	// the server, and — because the request wants a record kept EVERY time — appends exactly one audit
9	// record `INVOICE_PAID id=<id> amount=<amount>` per marking. Marking one invoice must not touch its
10	// siblings. (That payment is unavailable BEFORE an invoice is sent is covered by invoice-send.spec.)
11	//
12	// Asserts ONLY through the two public channels: the UI (data-testid) and the audit file
13	// (auditLines()). Data is arranged via resetAndSeed (the app's /__test__ endpoint): `clients`
14	// honours { id, name, email }, `projects` honours { id, name, clientId } and `invoices` honours
15	// { id, amount, projectId, status }.
16	import { test, expect, type Page, type Locator } from '@playwright/test';
17	import { resetAndSeed } from '../support/seed';
18	import { auditLines } from '../support/audit';
19	
20	// A status cell is "paid" when it carries the word "paid" on its own — matched case-insensitively so
21	// the test binds to the MEANING, not one capitalisation ("Paid"/"PAID"/"paid ✓" all count). The
22	// word boundary keeps the earlier "sent" stage from matching, so the same regex distinguishes a paid
23	// invoice from a not-yet-paid one without pinning the exact pre-payment wording.
24	const PAID = /\bpaid\b/i;
25	
26	const invoiceRows = (page: Page) => page.locator('[data-testid^="invoice-row-"]');
27	const statusOf = (page: Page, id: number): Locator =>
28	  page.getByTestId(`invoice-row-${id}`).getByTestId('invoice-status');
29	
30	// The audit record for one marking. The amount may be written bare (100) or with scale (100.00), so
31	// accept an optional fractional part; everything else is matched exactly.
32	const paidRecord = (id: number, amount: number) =>
33	  new RegExp(`^INVOICE_PAID id=${id} amount=${amount}(\\.\\d+)?$`);
34	
35	const paidRecordsFor = (id: number, amount: number): string[] =>
36	  auditLines().filter((line) => paidRecord(id, amount).test(line));
37	
38	test.describe('Mark an invoice as paid', () => {
39	  test('marking a sent invoice flips its status to paid, persists, and records it once', async ({
40	    page,
41	  }) => {
42	    await resetAndSeed({
43	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
44	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
45	      invoices: [{ id: 1, amount: 100, projectId: 1, status: 'SENT' }],
46	    });
47	
48	    await page.goto('/projects/1');
49	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
50	
51	    // The invoice has been sent but not yet paid, so it offers a control to mark it paid.
52	    await expect(statusOf(page, 1)).not.toHaveText(PAID);
53	    const pay = page.getByTestId('invoice-pay-1');
54	    await expect(pay).toBeVisible();
55	
56	    // Nothing has been recorded yet — reset clears the audit file, so the record below is proof the
57	    // marking (not the seeding) wrote it.
58	    expect(auditLines()).toEqual([]);
59	
60	    await pay.click();
61	
62	    // The status now reads paid.
63	    await expect(statusOf(page, 1)).toHaveText(PAID);
64	
65	    // And exactly one record was kept for this marking, carrying the invoice's id and amount.
66	    expect(paidRecordsFor(1, 100)).toHaveLength(1);
67	    expect(auditLines()).toHaveLength(1);
68	
69	    // The paid status is held by the server, not just the page: it survives a fresh load, and
70	    // reloading does not record the marking a second time.
